ALTER TABLE `adc_business`.`Patient` ADD CONSTRAINT `ck_Patient_1` CHECK (allergy_review_status IN ('NOT_REVIEWED','NO_KNOWN','RECORDED'));
ALTER TABLE `adc_business`.`Dentist` ADD CONSTRAINT `ck_Dentist_1` CHECK (termination_date IS NULL OR termination_date >= hire_date);
ALTER TABLE `adc_business`.`DentistQualification` ADD CONSTRAINT `ck_DentistQualification_1` CHECK (expiry_date IS NULL OR expiry_date >= granted_date);
ALTER TABLE `adc_business`.`DentistSchedule` ADD CONSTRAINT `ck_DentistSchedule_1` CHECK (schedule_status IN ('NORMAL','SUSPENDED'));
ALTER TABLE `adc_business`.`DentistSchedule` ADD CONSTRAINT `ck_DentistSchedule_2` CHECK (end_time > start_time AND slot_minutes > 0 AND MOD(TIME_TO_SEC(end_time)-TIME_TO_SEC(start_time),slot_minutes*60)=0);
ALTER TABLE `adc_business`.`Appointment` ADD CONSTRAINT `ck_Appointment_1` CHECK (status IN ('SCHEDULED','CANCELLED','IN_PROGRESS','COMPLETED','INVOICED'));
ALTER TABLE `adc_business`.`Appointment` ADD CONSTRAINT `ck_Appointment_2` CHECK ((status='CANCELLED' AND cancelled_at IS NOT NULL AND cancellation_reason IS NOT NULL AND CHAR_LENGTH(TRIM(cancellation_reason))>0 AND cancellation_kind IS NOT NULL AND cancellation_kind IN ('PATIENT_CANCEL','NO_SHOW','CLINIC_RESCHEDULE','CLINIC_CANCEL') AND attended_at IS NULL AND completed_at IS NULL) OR (status<>'CANCELLED' AND cancelled_at IS NULL AND cancellation_reason IS NULL AND cancellation_kind IS NULL AND ((status='SCHEDULED' AND attended_at IS NULL AND completed_at IS NULL) OR (status='IN_PROGRESS' AND attended_at IS NOT NULL AND completed_at IS NULL) OR (status IN ('COMPLETED','INVOICED') AND attended_at IS NOT NULL AND completed_at IS NOT NULL))));
ALTER TABLE `adc_business`.`AppliedTreatment` ADD CONSTRAINT `ck_AppliedTreatment_1` CHECK (standard_units>0 AND unit_price>=0 AND subtotal=ROUND(standard_units*unit_price,2));
ALTER TABLE `adc_business`.`InvoiceItem` ADD CONSTRAINT `ck_InvoiceItem_1` CHECK (line_number>0 AND standard_units>0 AND unit_price>=0 AND subtotal=ROUND(standard_units*unit_price,2));
ALTER TABLE `adc_business`.`CostEntry` ADD CONSTRAINT `ck_CostEntry_1` CHECK (cost_type IN ('MEDICAL_SUPPLY','OPERATING'));
ALTER TABLE `adc_business`.`CostEntry` ADD CONSTRAINT `ck_CostEntry_2` CHECK ((reversal_of_id IS NULL AND amount>=0) OR (reversal_of_id IS NOT NULL AND amount<0));
ALTER TABLE `adc_business`.`QuarterlyPerformance` ADD CONSTRAINT `ck_QuarterlyPerformance_1` CHECK (calculation_version>0 AND quarter_end>quarter_start AND incentive_rate=0.1000);
ALTER TABLE `adc_business`.`QuarterlyPerformance` ADD CONSTRAINT `ck_QuarterlyPerformance_2` CHECK (calculation_status IN ('DRAFT','INCOMPLETE','CALCULATED','PUBLISHED','SUPERSEDED'));
ALTER TABLE `adc_business`.`QuarterlyPerformance` ADD CONSTRAINT `ck_QuarterlyPerformance_3` CHECK ((net_profit IS NULL OR revenue IS NULL OR medical_supply_cost IS NULL OR operating_expense IS NULL OR net_profit=revenue-medical_supply_cost-operating_expense) AND (incentive_amount IS NULL OR net_profit IS NULL OR incentive_amount=ROUND(GREATEST(net_profit,0)*incentive_rate,2)));
ALTER TABLE `adc_business`.`QuarterlyPerformance` ADD CONSTRAINT `ck_QuarterlyPerformance_4` CHECK (calculation_status NOT IN ('CALCULATED','PUBLISHED','SUPERSEDED') OR (revenue IS NOT NULL AND medical_supply_cost IS NOT NULL AND operating_expense IS NOT NULL AND net_profit IS NOT NULL AND incentive_amount IS NOT NULL));
ALTER TABLE `adc_business`.`QuarterlyPerformance` ADD CONSTRAINT `ck_QuarterlyPerformance_5` CHECK (calculation_status NOT IN ('PUBLISHED','SUPERSEDED') OR published_at IS NOT NULL);
ALTER TABLE `adc_business`.`AppointmentEvent` ADD CONSTRAINT `ck_AppointmentEvent_1` CHECK ((event_type='BOOK' AND from_status IS NULL AND to_status='SCHEDULED') OR (from_status IS NOT NULL AND ((event_type='ATTEND' AND from_status='SCHEDULED' AND to_status='IN_PROGRESS') OR (event_type='CANCEL' AND from_status='SCHEDULED' AND to_status='CANCELLED') OR (event_type='COMPLETE' AND from_status='IN_PROGRESS' AND to_status='COMPLETED') OR (event_type='INVOICE' AND from_status='COMPLETED' AND to_status='INVOICED'))));
ALTER TABLE `adc_identity`.`Subject` ADD CONSTRAINT `ck_Subject_1` CHECK (subject_type IN ('PATIENT','STAFF','SYSTEM'));
ALTER TABLE `adc_identity`.`Subject` ADD CONSTRAINT `ck_Subject_2` CHECK (is_enabled IN (0,1));
ALTER TABLE `adc_identity`.`ExternalIdentity` ADD CONSTRAINT `ck_ExternalIdentity_1` CHECK (provider='WECHAT_MINIPROGRAM');
ALTER TABLE `adc_identity`.`Session` ADD CONSTRAINT `ck_Session_1` CHECK (client_type IN ('WEB','WECHAT') AND (client_type<>'WEB' OR csrf_secret_hash IS NOT NULL));
ALTER TABLE `adc_identity`.`LoginThrottle` ADD CONSTRAINT `ck_LoginThrottle_1` CHECK (consecutive_failures>=0);
ALTER TABLE `adc_identity`.`BindingRequest` ADD CONSTRAINT `ck_BindingRequest_1` CHECK (status IN ('PENDING','APPROVED'));
ALTER TABLE `adc_identity`.`BindingRequest` ADD CONSTRAINT `ck_BindingRequest_2` CHECK ((status='PENDING' AND candidate_patient_id IS NULL AND reviewed_by IS NULL AND reviewed_at IS NULL AND verification_basis IS NULL) OR (status='APPROVED' AND candidate_patient_id IS NOT NULL AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL AND verification_basis IS NOT NULL));
ALTER TABLE `adc_identity`.`BindingEvent` ADD CONSTRAINT `ck_BindingEvent_1` CHECK ((action='BIND' AND old_subject_id IS NULL AND new_subject_id IS NOT NULL AND binding_request_id IS NOT NULL) OR (action='REBIND' AND old_subject_id IS NOT NULL AND new_subject_id IS NOT NULL AND old_subject_id<>new_subject_id AND binding_request_id IS NOT NULL) OR (action='UNBIND' AND old_subject_id IS NOT NULL AND new_subject_id IS NULL));
ALTER TABLE `adc_identity`.`AccessGrant` ADD CONSTRAINT `ck_AccessGrant_1` CHECK (role_code IN ('RECEPTION','DENTIST','CASHIER','HEADQUARTERS'));
ALTER TABLE `adc_identity`.`AccessGrant` ADD CONSTRAINT `ck_AccessGrant_2` CHECK (valid_until IS NULL OR valid_until>valid_from);
ALTER TABLE `adc_identity`.`AccessGrant` ADD CONSTRAINT `ck_AccessGrant_3` CHECK ((revoked_at IS NULL AND revoked_by IS NULL) OR (revoked_at IS NOT NULL AND revoked_by IS NOT NULL));
